import{_ as s,o as t,c as e,a2 as i}from"./chunks/framework.BZO4qERu.js";const k=JSON.parse('{"title":"技能","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guides/skills.md","filePath":"zh/guides/skills.md","lastUpdated":1792323081000}'),l={name:"zh/guides/skills.md"};function d(n,a,o,r,p,c){return t(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="技能" tabindex="-1">技能 <a class="header-anchor" href="#技能" aria-label="Permalink to &quot;技能&quot;">​</a></h1><p>**技能（Skill）**是可复用的提示模块，用来教 Bot 一套固定做法：语气、流程、工具使用习惯。技能没有单独的管理界面——它就是工作区里的文件，放对目录就会被加载。</p><div class="tip custom-block"><p class="custom-block-title">限制</p><p>一次会话最多同时请求 5 个技能；单个技能注入上限 64 KiB，合计上限 256 KiB。这些上限不可配置。</p></div><h2 id="长什么样" tabindex="-1">长什么样 <a class="header-anchor" href="#长什么样" aria-label="Permalink to &quot;长什么样&quot;">​</a></h2><p>一个技能是一个目录，里面放一份带 YAML 头的 <code>SKILL.md</code>，至少要有稳定的 <code>name</code> 和短 <code>description</code>。正文就是真正注入给 Agent 的说明：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">---</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">coder-skill</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Enables advanced coding workflows and tool usage.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Coder Skill</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">你写清楚代码、说明取舍，该用文件/命令工具时就用。</span></span></code></pre></div><p>名字用简单 ASCII（如 <code>coder-skill</code>、<code>research</code>），别带空格——它同时也是目录名。</p><h2 id="放到哪个目录" tabindex="-1">放到哪个目录 <a class="header-anchor" href="#放到哪个目录" aria-label="Permalink to &quot;放到哪个目录&quot;">​</a></h2><p>自己写的技能，放进 Bot 工作区的这个目录：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/data/skills/user/personal/&lt;技能名&gt;/SKILL.md</span></span></code></pre></div><p>怎么放都行：在 Bot 的 <strong>文件</strong> 标签页里直接建目录写文件，在 <strong>终端</strong> 里操作，或者干脆让 Bot 自己建——工作区自带一个 <code>skill-creator</code> 技能，描述清楚你要的流程，它会把文件写到正确的位置。</p><p>其它目录你会见到，但<strong>不该手动往里放东西</strong>：</p><table tabindex="0"><thead><tr><th>目录</th><th>归谁管</th></tr></thead><tbody><tr><td><code>/data/skills/user/personal/</code></td><td><strong>你</strong>。手写技能都放这里</td></tr><tr><td><code>/data/skills/&lt;registry&gt;/&lt;app&gt;/</code></td><td><a href="./supermarket.html">应用</a>。随 App 安装、更新、卸载，别手改</td></tr><tr><td><code>/data/.memoh/skills/</code></td><td>工作区模板的内置技能（如 <code>skill-creator</code>）。每次工作区初始化都会刷成模板版本，改了也会被覆盖；要定制就换个名字复制到自己的目录</td></tr><tr><td><code>/data/.skills/</code>、<code>/data/.agents/skills/</code></td><td>旧版兼容路径，仅作发现，不要新增</td></tr></tbody></table><h2 id="同名怎么办" tabindex="-1">同名怎么办 <a class="header-anchor" href="#同名怎么办" aria-label="Permalink to &quot;同名怎么办&quot;">​</a></h2><p><strong>技能名就是身份</strong>：同名技能不管来自几个目录，同一时刻只有一份生效。你自己目录里的同名技能会盖过旧版兼容路径里的那份。想换掉某个 App 技能的行为，别去改它的文件——用一个新名字写你的版本。</p><h2 id="建议" tabindex="-1">建议 <a class="header-anchor" href="#建议" aria-label="Permalink to &quot;建议&quot;">​</a></h2><ol><li>先少而精，<code>name</code> 和 <code>description</code> 写清楚——Agent 靠描述决定要不要加载它。</li><li>重复出现的流程才值得固化成技能；一次性的要求直接说就行。</li><li>能复用就从<a href="./supermarket.html">应用市场</a>装，少复制粘贴多份。</li></ol>`,17)])])}const g=s(l,[["render",d]]);export{k as __pageData,g as default};
